record.field:
for record in records:
        if record.x_studio_almacen:
                # Obtener las ubicaciones relacionadas con el almacén
                location_ids = env['stock.location'].search([
                ('location_id', 'child_of', [record.x_studio_almacen.view_location_id.id])
                ]).ids
                if location_ids:
                        # Buscar todos los productos, incluidos los kits
                        products = env['product.product'].search([
                        ('location_id', 'in', location_ids)
                        ])
                        # Limpiar los registros existentes en x_studio_inventarios
                        record.x_studio_inventarios.unlink()
                        # Crear nuevos registros con las existencias agrupadas por producto
                        for product in products:
                                product_qty = 0 # Inicializar cantidad del producto
                                if product.bom_ids: # Verificar si el producto tiene una lista de materiales
                                        # Calcular la existencia del kit basándose en sus componentes
                                        quantities = []
                                        for bom_line in product.bom_ids.bom_line_ids:
                                                component_qty = sum(bom_line.product_id.stock_quant_ids.filtered(
                                                        lambda q: q.location_id.id in location_ids).mapped('available_quantity'))
                                                quantities.append(component_qty // bom_line.product_qty if bom_line.product_qty > 0 else 0)
                                        product_qty = min(quantities) if quantities else 0

                                else:
                                        product_qty = sum(product.stock_quant_ids.filtered(
                                        lambda q: q.location_id.id in location_ids).mapped('available_quantity'))
                                        # Solo crear un registro si la cantidad es mayor que cero
                                if product_qty > -1:
                                        env['x_lininvsync'].create({
                                        'x_studio_inventario_por_ubicacin': record.id,
                                        'x_studio_producto': product.id,
                                        'x_name': product.display_name,
                                        'x_studio_stock': product_qty,
                                        })

# Acción de servidor para llenar x_az_prices con combinaciones producto/canal

# 1. Limpiar registros existentes
env['x_az_prices'].search([]).unlink()

# 2. Buscar todas las listas de precios sincronizables
pricelists = env['product.pricelist'].search([('x_studio_az_sync', '=', True)])

registros_creados = 0

for pricelist in pricelists:
    canales = pricelist.x_studio_canales
    if not canales:
        continue

    for item in pricelist.item_ids:
        # Resolver variantes según el tipo de línea de la lista de precios
        if item.product_id:
            # La línea apunta a una variante específica
            variantes = item.product_id
        elif item.product_tmpl_id:
            # La línea apunta a una plantilla → obtener todas sus variantes activas tipo 'consu'
            variantes = item.product_tmpl_id.product_variant_ids.filtered(
                lambda v: v.active and v.type in ['consu']
            )
        else:
            # La línea aplica a toda la categoría o a todos los productos → omitir
            continue

        for product in variantes:
            for canal in canales:
                precio = pricelist._get_product_price(product, 1.0)

                if not precio:
                    precio = product.list_price

                env['x_az_prices'].create({
                    'x_studio_producto': product.id,
                    'x_studio_canal': canal.id,
                    'x_studio_pricelist': pricelist.id,
                    'x_studio_precio': precio,
                })

                registros_creados += 1

#raise UserError(f"Proceso completado. Registros creados: {registros_creados}")

# Acción Automatizada para calcular margen en sale.order
# Activador: Al crear y actualizar
# Modelo: sale.order

# ========== CONFIGURACIÓN DE RANGOS ==========
RANGO_EXCELENTE = 15    # >= % - Verde
RANGO_BUENO = 5        # >= % - Amarillo
RANGO_REGULAR = 0       # >= % - Naranja
# < 0% - Rojo (pérdida)

# Configuración de colores y iconos
COLORES = {
    'excelente': {'fondo': '#d4edda', 'texto': '#155724', 'icono': '🟢'},
    'bueno': {'fondo': '#fff3cd', 'texto': '#856404', 'icono': '🟡'},
    'regular': {'fondo': '#ffeaa7', 'texto': '#d35400', 'icono': '🟠'},
    'malo': {'fondo': '#f8d7da', 'texto': '#721c24', 'icono': '🔴'}
}
# ============================================

for record in records:
    # Total de venta (con impuestos incluidos)
    total_venta = record.amount_total

    # Calcular costos totales
    total_costo_productos = 0
    total_envios_comisiones = 0

    # Sumar costos de productos con IVA
    for line in record.order_line:
        # Aplicar IVA al costo (ajustar porcentaje según corresponda)
        costo_con_iva = line.product_id.standard_price * line.product_uom_qty
        total_costo_productos += costo_con_iva

    # Sumar envíos y comisiones
    for envcom_line in record.x_studio_lineenvcom:
        total_envios_comisiones += envcom_line.x_studio_subtotal

    # Calcular ganancia y margen
    ganancia = total_venta - total_costo_productos - total_envios_comisiones
    margen_porcentaje = (ganancia / total_venta * 100) if total_venta > 0 else 0

    # Determinar categoría según rangos
    if margen_porcentaje >= RANGO_EXCELENTE:
        categoria = 'excelente'
    elif margen_porcentaje >= RANGO_BUENO:
        categoria = 'bueno'
    elif margen_porcentaje >= RANGO_REGULAR:
        categoria = 'regular'
    else:
        categoria = 'malo'

    # Obtener colores e icono
    config_color = COLORES[categoria]

    # Generar HTML del margen
    html_margen = f"""
    <div style="
        background: {config_color['fondo']};
        color: {config_color['texto']};
        padding: 4px 8px;
        border-radius: 6px;
        font-weight: 600;
        text-align: center;
        border: 1px solid {config_color['texto']}20;
        font-size: 12px;
        display: inline-flex;
        align-items: center;
        gap: 4px;
        white-space: nowrap;
    ">
        <span>{config_color['icono']}</span>
        <span>${ganancia:,.0f}</span>
        <span style="font-size: 10px; opacity: 0.8;">({margen_porcentaje:+.0f}%)</span>
    </div>
    """

    # Asignar al campo
    record['x_studio_analisis_de_margen'] = html_margen
